// Define options and their scores
const options = [
  { name: 'Option A', score: 5 },
  { name: 'Option B', score: 3 },
  { name: 'Option C', score: 2 },
  { name: 'Option D', score: 1 }
];
// Get user input
const userInput = prompt('Which option do you prefer?');
// Find the selected option and display the result
const selectedOption = options.find(option => option.name === userInput);
alert(`You selected ${selectedOption.name}, which has a score of ${selectedOption.score}.`);
// Calculate the total score of all options
const totalScore = options.reduce((acc, option) => acc + option.score, 0);
// Calculate the percentage of the total score that the selected option represents
const selectedOptionPercentage = selectedOption.score / totalScore * 100;
// Display the percentage
alert(`Your selected option represents ${selectedOptionPercentage}% of the total score.`);
```
