const article = "This is an axample of an artical with some misspelled words.";
const dictionary = ["example", "article", "misspelled", "words"];
// Split the article into an array of words
const words = article.split(" ");
// Loop through each word and check if it's spelled correctly
for (let i = 0; i < words.length; i++) {
  const word = words[i];
  const result = checkSpelling(word, dictionary);
  if (result === "Misspelled") {
    console.log(`The word "${word}" is misspelled.`);
  }
