};
function startChat() {
  console.log(chatbot.greeting);
  for (let i = 0; i < chatbot.prompts.length; i++) {
    const prompt = chatbot.prompts[i].prompt;
    const response = chatbot.prompts[i].response;
    let answer = promptUser(prompt);
    let output = response(answer);
    console.log(output);
  }
  console.log(chatbot.end);
}
function promptUser(prompt) {
  let answer = prompt(prompt);
  return answer;
}
startChat();
```
