public class HistoricalEventFinder {
  public static void main(String[] args) {
    String url = "https://api.datamuse.com/words?rel_syn=";
    String keyword = "renaissance";
    String query = "https://en.wikipedia.org/w/api.php?action=query&format=json&prop=extracts&exintro&explaintext&redirects=1&titles=";
    String event = "";
    String location = "";
    String date = "";
    String summary = "";

    try {
      URL datamuse = new URL(url + keyword);
      BufferedReader in = new BufferedReader(new InputStreamReader(datamuse.openStream()));
      JSONArray jsonArray = new JSONArray(in.readLine());
      in.close();

      for (int i = 0; i < jsonArray.length(); i++) {
        JSONObject jsonObject = jsonArray.getJSONObject(i);
        event = jsonObject.getString("word");

        URL wikipedia = new URL(query + URLEncoder.encode(event, "UTF-8"));
        BufferedReader reader = new BufferedReader(new InputStreamReader(wikipedia.openStream()));
        JSONObject json = new JSONObject(reader.readLine());
        reader.close();

        JSONObject pages = json.getJSONObject("query").getJSONObject("pages");
        String pageId = pages.keys().next();
        JSONObject page = pages.getJSONObject(pageId);
        summary = page.getString("extract");

        if (summary.contains("15th century") && summary.contains("1400") && summary.contains("1499")) {
          int start = summary.indexOf("date") + 5;
          int end = summary.indexOf(".", start);
          date = summary.substring(start, end);
          start = summary.indexOf("location") + 9;
          end = summary.indexOf(".", start);
          location = summary.substring(start, end);
          break;
        }
      }

      System.out.println("Event: " + event);
      System.out.println("Location: " + location);
      System.out.println("Date: " + date);
      System.out.println("Summary: " + summary);

    } catch (Exception e) {
      e.printStackTrace();
    }
  }
}
```
