How can I determine the length of the longest increasing subsequence of at least three elements in a given list using C#? The list is {5, 4, 3, 2, 7, 6, 1}.
Here is a possible solution:
int[] nums = { 5, 4, 3, 2, 7, 6, 1 };
int n = nums.Length;
int[] dp = new int[n];
int maxLen = 0;
for (int i = 0; i < n; i++)
{
    dp[i] = 1;
    for (int j = 0; j < i; j++)
    {
        if (nums[i] > nums[j])
        {
            dp[i] = Math.Max(dp[i], dp[j] + 1);
        }
    }
    maxLen = Math.Max(maxLen, dp[i]);
}
if (maxLen < 3)
{
    Console.WriteLine("There is no increasing subsequence of at least three elements.");
}
else
{
    Console.WriteLine("The length of the longest increasing subsequence of at least three elements is {0}.", maxLen);
}

