#include <iostream>
#include <cmath>
using namespace std;
int main() {
  double dataset[] = {2, 4, -5, 6, 8, 10};
  int n = sizeof(dataset) / sizeof(double);
  double sum = 0, mean, variance, stddev;
  // Calculate the mean
  for (int i = 0; i < n; i++) {
    sum += dataset[i];
  }
  mean = sum / n;
  // Calculate the variance
  sum = 0;
  for (int i = 0; i < n; i++) {
    sum += pow(dataset[i] - mean, 2);
  }
  variance = sum / n;
  // Calculate the standard deviation
  stddev = sqrt(variance);
  cout << "The standard deviation is: " << stddev << endl;
  return 0;
}

