    query := "SELECT * FROM Employees ORDER BY id DESC LIMIT 1"
    // Execute the query and get the result
    var id int
    var name string
    var age int
    err = db.QueryRow(query).Scan(&id, &name, &age)
    if err != nil {
        panic(err.Error())
    }
    // Print the result
    fmt.Printf("Last Employee: id=%d, name=%s, age=%d\n", id, name, age)
}
